  out.worldPosition = worldPosition4.xyz;
  out.worldNormal = worldNormal4.xyz;
  out.uv = uv * object.uvTransform.zw + object.uvTransform.xy;
  out.mappingPosition = (object.mappingModel * vec4<f32>(position, 1.0)).xyz;
  out.mappingNormal = (object.mappingNormalMatrix * vec4<f32>(normal, 0.0)).xyz;
