  let sampleY = textureSample(baseColorTexture, materialSampler, fract(localPosition.xz));
  let sampleZ = textureSample(baseColorTexture, materialSampler, fract(localPosition.xy));
  return sampleX * weights.x + sampleY * weights.y + sampleZ * weights.z;
