  let reflectionStrength = mix(0.18, 1.0, metallic);
  let roughnessDiffuseBias = 1.0 - roughness * 0.2;
  let roughnessReflectionBias = 1.0 - roughness * 0.25;

  let litColor =
    diffuseColor * roughnessDiffuseBias +
    diffuseColor * directLight +
    diffuseColor * skyLight +
    directSpecular +
    skySpecular +
    reflectionColor * reflectionStrength * roughnessReflectionBias +
    emissive;

